 <!DOCTYPE html>
 <html lang="pl">
 <head>
   <meta charset="UTF-8" />
   <meta name="viewport" content="width=device-width, initial-scale=1.0" />
   <title>Lampa 2 – Sollux</title>
   <script src="https://cdn.tailwindcss.com"></script>
   <style>
     .svg-lamp {
       cursor: pointer;
       user-select: none;
     }

     .svg-lamp > img {
       display: block;
       width: 100%;
       height: auto;
     }

     .svg-lamp > svg {
       position: absolute;
       inset: 0;
       width: 100%;
       height: 100%;
       pointer-events: none;
     }

     .lamp-light {
       opacity: 0;
       transition: opacity 250ms cubic-bezier(0.4, 0, 0.2, 1),
                   fill 250ms cubic-bezier(0.4, 0, 0.2, 1),
                   filter 250ms cubic-bezier(0.4, 0, 0.2, 1);
     }

     .svg-lamp.is-lit .lamp-light {
       opacity: 1;
       fill: url(#lamp2Glow);
       filter:
               drop-shadow(0 0 28px rgba(255, 160, 75, 0.7));
     }
   </style>
 </head>
 <body class="bg-white min-h-screen flex items-center justify-center p-6">
   <main class="flex flex-col items-center gap-4">
     <button
       type="button"
       data-svg-lamp
       aria-pressed="false"
       aria-label="Włącz lampę"
       class="svg-lamp relative block w-64 sm:w-80 focus:outline-none focus-visible:ring-2 focus-visible:ring-[#E5BA2C] rounded-3xl"
     >
       <img
         src="./assets/images/lampa2.svg"
         alt=""
         aria-hidden="true"
         draggable="false"
       />
       <svg
         data-lamp-overlay
         xmlns="http://www.w3.org/2000/svg"
         viewBox="0 0 1056 976"
         preserveAspectRatio="none"
         aria-hidden="true"
       >
         <defs>
           <radialGradient id="lamp2Glow" cx="50%" cy="50%" r="50%">
             <stop offset="0%" stop-color="#FFFDF5" />
             <stop offset="55%" stop-color="#FFE6A3" />
             <stop offset="88%" stop-color="#F5B841" stop-opacity="0.9" />
             <stop offset="100%" stop-color="#E5B08A" />
           </radialGradient>
         </defs>
       </svg>
     </button>
     <p data-lamp-error role="alert" class="text-sm text-red-700" hidden>
       Nie udało się wczytać wektorowego konturu lampy.
     </p>
   </main>

   <script>
     const lamp = document.querySelector("[data-svg-lamp]");
     const overlay = document.querySelector("[data-lamp-overlay]");
     const errorMessage = document.querySelector("[data-lamp-error]");

     lamp.addEventListener("click", () => {
       const isLit = lamp.classList.toggle("is-lit");
       lamp.setAttribute("aria-pressed", String(isLit));
       lamp.setAttribute("aria-label", isLit ? "Wyłącz lampę" : "Włącz lampę");
     });

     async function loadLampLight() {
       const response = await fetch("./assets/lampa-2-vector.svg");
       if (!response.ok) {
         throw new Error(`Vector SVG request failed: ${response.status}`);
       }

       const svgText = await response.text();
       const vectorDocument = new DOMParser().parseFromString(
         svgText,
         "image/svg+xml"
       );
       if (vectorDocument.querySelector("parsererror")) {
         throw new Error("Vector SVG could not be parsed.");
       }

       const diffuserPath = vectorDocument.querySelector(
         'path[fill="#F5C7A5"][d^="M146.38 674.34"]'
       );
       if (!diffuserPath) {
         throw new Error("The lamp diffuser path was not found in the vector SVG.");
       }

       const importedDiffuser = document.importNode(diffuserPath, true);
       importedDiffuser.setAttribute("class", "lamp-light");
       overlay.append(importedDiffuser);
     }

     loadLampLight().catch((error) => {
       console.error("Could not load the lamp's vector light path.", error);
       lamp.disabled = true;
       errorMessage.hidden = false;
     });
   </script>
 </body>
 </html>

